@* Search input for filtering tasks by title *@

<div class="mb-3">
    <input type="text"
           class="form-control"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await OnSearchChanged.InvokeAsync(value);
    }
}

@* A single Kanban column displaying task cards and an optional add-task form *@

<div class="col-md-4">
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body" style="min-height: 200px; max-height: 70vh; overflow-y: auto;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          ShowMoveLeft="HasLeftColumn"
                          ShowMoveRight="HasRightColumn"
                          OnMoveLeft="() => HandleMoveLeft(task)"
                          OnMoveRight="() => HandleMoveRight(task)" />
            }

            @if (ShowAddForm)
            {
                <AddTaskForm OnSave="HandleNewTask" OnCancel="() => ShowAddForm = false" />
            }
        </div>
        <div class="card-footer">
            <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => ShowAddForm = true" disabled="@ShowAddForm">
                + Add Task
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter] public bool HasLeftColumn { get; set; }
    [Parameter] public bool HasRightColumn { get; set; }
    [Parameter] public string? LeftColumnStatus { get; set; }
    [Parameter] public string? RightColumnStatus { get; set; }
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnTaskMoved { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskModel> OnTaskCreated { get; set; }

    private bool ShowAddForm { get; set; }

    private async Task HandleMoveLeft(TaskItem task)
    {
        if (LeftColumnStatus is not null)
        {
            await OnTaskMoved.InvokeAsync((task.Id, LeftColumnStatus));
        }
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        if (RightColumnStatus is not null)
        {
            await OnTaskMoved.InvokeAsync((task.Id, RightColumnStatus));
        }
    }

    private async Task HandleNewTask(AddTaskForm.NewTaskModel model)
    {
        await OnTaskCreated.InvokeAsync(model);
        ShowAddForm = false;
    }
}

